part of 'user_cubit.dart';@immutableclass UserClassState {  final bool loading;  final String error;  final bool? success;  const UserClassState({    this.loading = false,    this.error = '',    this.success,  });  UserClassState copyWith({    bool? loading,    String? message,    String? error,    bool? success,  }) {    return UserClassState(      loading: loading ?? this.loading,      error: error ??   this.error,      success: success ?? this.success,    );  }}